// ─── File: EventsBoundaryDemo.java ───
// Runnable demo: internal domain event (in-process) + external integration event (ACL + Kafka).

import java.math.BigDecimal;
import java.util.*;
import java.util.function.Consumer;
import java.util.logging.*;

public class EventsBoundaryDemo {

    private static final Logger log = Logger.getLogger("events");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // In-process domain-event bus (stand-in for Spring ApplicationEventPublisher).
        InProcessBus bus = new InProcessBus();
        bus.subscribe(new DailyTotalListener());
        bus.subscribe(new FeeCacheListener());

        KafkaPublisher kafka = new KafkaPublisher();
        IntegrationEventTranslator acl = new IntegrationEventTranslator(kafka);
        bus.subscribe(acl);   // translates domain → integration event at the boundary

        // Consumer in ANOTHER service sees only the integration event.
        kafka.subscribe(new NotificationConsumer());

        // Complete a transfer on the internal aggregate.
        TransferAggregate aggregate = new TransferAggregate("SAV2001", "BENEF-77", new BigDecimal("50000"));
        TransferCompletedDomainEvent domainEvent = aggregate.complete();
        bus.publish(domainEvent);   // in-process; listeners + ACL react
    }
}

// ─── domain/TransferAggregate.java — INTERNAL model ───
class TransferAggregate {
    final String accountId; final String beneficiary; final BigDecimal amount;
    String internalLedgerRef = "LEDGER-" + UUID.randomUUID();   // internal detail, never exposed
    int internalRiskBucket = 2;                                  // internal detail, never exposed
    TransferAggregate(String accountId, String beneficiary, BigDecimal amount) {
        this.accountId = accountId; this.beneficiary = beneficiary; this.amount = amount;
    }
    TransferCompletedDomainEvent complete() {
        return new TransferCompletedDomainEvent(this);   // carries the whole internal aggregate
    }
}

// ─── domain/TransferCompletedDomainEvent.java — INTERNAL, in-process ───
class TransferCompletedDomainEvent {
    final TransferAggregate aggregate;   // rich internal model — fine, never leaves the service
    TransferCompletedDomainEvent(TransferAggregate aggregate) { this.aggregate = aggregate; }
}

// ─── listener/DailyTotalListener.java — in-process side effect ───
class DailyTotalListener implements Consumer<TransferCompletedDomainEvent> {
    private static final Logger log = Logger.getLogger("events");
    public void accept(TransferCompletedDomainEvent e) {
        log.info(() -> "[DOMAIN] DailyTotalListener: added Rs." + e.aggregate.amount
                + " to daily total for " + e.aggregate.accountId
                + " (ledgerRef=" + e.aggregate.internalLedgerRef + ")");  // uses internal detail freely
    }
}

// ─── listener/FeeCacheListener.java — in-process side effect ───
class FeeCacheListener implements Consumer<TransferCompletedDomainEvent> {
    private static final Logger log = Logger.getLogger("events");
    public void accept(TransferCompletedDomainEvent e) {
        log.info(() -> "[DOMAIN] FeeCacheListener: refreshed fee cache for risk bucket "
                + e.aggregate.internalRiskBucket);   // uses internal detail freely
    }
}

// ─── integration/TransferCompletedIntegrationEvent.java — EXTERNAL, versioned ───
class TransferCompletedIntegrationEvent {
    final String eventId; final String accountId; final String beneficiary;
    final BigDecimal amount; final long occurredAt; final int schemaVersion = 1;
    TransferCompletedIntegrationEvent(String eventId, String accountId, String beneficiary, BigDecimal amount) {
        this.eventId = eventId; this.accountId = accountId; this.beneficiary = beneficiary;
        this.amount = amount; this.occurredAt = System.currentTimeMillis();
    }
    // NOTE: no internalLedgerRef, no internalRiskBucket — internals are NOT exposed.
}

// ─── acl/IntegrationEventTranslator.java — the Anti-Corruption Layer ───
class IntegrationEventTranslator implements Consumer<TransferCompletedDomainEvent> {
    private static final Logger log = Logger.getLogger("events");
    private final KafkaPublisher kafka;
    IntegrationEventTranslator(KafkaPublisher kafka) { this.kafka = kafka; }
    public void accept(TransferCompletedDomainEvent e) {
        // Translate internal model → curated external schema (only safe fields).
        TransferCompletedIntegrationEvent ext = new TransferCompletedIntegrationEvent(
                "EVT-" + UUID.randomUUID().toString().substring(0, 8),
                e.aggregate.accountId, e.aggregate.beneficiary, e.aggregate.amount);
        log.info(() -> "[ACL] translated domain event → integration event v" + ext.schemaVersion
                + " (internals stripped)");
        // Key by aggregate-root id → per-account ordering on the Kafka partition.
        kafka.publish(ext.accountId, ext);
    }
}

// ─── publish/KafkaPublisher.java — stand-in for Kafka + Schema Registry ───
class KafkaPublisher {
    private static final Logger log = Logger.getLogger("events");
    private final List<Consumer<TransferCompletedIntegrationEvent>> consumers = new ArrayList<>();
    void subscribe(Consumer<TransferCompletedIntegrationEvent> c) { consumers.add(c); }
    void publish(String key, TransferCompletedIntegrationEvent e) {
        log.info(() -> "[KAFKA] produce key=" + key + " topic=transfer.completed (ordered per key)");
        consumers.forEach(c -> c.accept(e));
    }
}

// ─── notification-service/NotificationConsumer.java — sees ONLY the integration event ───
class NotificationConsumer implements Consumer<TransferCompletedIntegrationEvent> {
    private static final Logger log = Logger.getLogger("events");
    public void accept(TransferCompletedIntegrationEvent e) {
        log.info(() -> "[NOTIFY] SMS: transfer of Rs." + e.amount + " to " + e.beneficiary
                + " for account " + e.accountId + " (consumer never saw producer internals)");
    }
}

// ─── InProcessBus.java — stand-in for Spring ApplicationEventPublisher ───
class InProcessBus {
    private final List<Consumer<TransferCompletedDomainEvent>> subs = new ArrayList<>();
    void subscribe(Consumer<TransferCompletedDomainEvent> s) { subs.add(s); }
    void publish(TransferCompletedDomainEvent e) { subs.forEach(s -> s.accept(e)); }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
